// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am, uint256 _lockTime, uint256 _minSum) public {
        // Bound lockTime and minSum to reasonable values
        _lockTime = bound(_lockTime, 0, 1e9);
        _minSum = bound(_minSum, 0, 1e18);

        // Initialize the contract
        c.SetMinSum(_minSum);
        c.Initialized();

        // Try to call Collect - may fail
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", _am));

        // After Collect, attempt to call SetMinSum - should revert in reference, succeed in mutant
        bool setReverted = false;
        try c.SetMinSum(0) {
            setReverted = false;
        } catch {
            setReverted = true;
        }

        // Reference: after initialization, SetMinSum should revert
        assertTrue(setReverted, "SetMinSum should revert after initialization");
    }
}

